<script lang="ts">
	// @ts-nocheck
	import data from '$data'
	const field_types = ['string', 'number', 'integer', 'boolean', 'file', 'object', 'array_string', 'array_number', 'array_integer', 'array_boolean', 'array_object', 'array_file']
	const blank = () => ({ id: '', name: '', label: '', type: 'string', required: false, description: '', placeholder: '', default_value: null, object_spec: null, order: 0, show_in_list: false, searchable: false })
	let input_fields = $state([]), output_fields = $state([]), config_rows = $state([]), tab = $state('input'), editing = $state(''), draft = $state(blank()), saving = $state(false), error = $state(''), notice = $state(''), import_open = $state(false), import_json = $state('{}')
	let config_form = $state({ id: '', default_refresh_seconds: 10 })
	data.smart_workflow_input_fields.subscribe((items) => input_fields = [...items].sort((a, b) => (a.order || 0) - (b.order || 0)))
	data.smart_workflow_output_fields.subscribe((items) => output_fields = [...items].sort((a, b) => (a.order || 0) - (b.order || 0)))
	data.smart_workflow_runner_config.subscribe((items) => { const row = items[0]; if (row) config_form = { id: row.id, default_refresh_seconds: Number(row.default_refresh_seconds || 0) } })
	const fields = () => tab === 'input' ? input_fields : output_fields
	const collection = () => tab === 'input' ? data.smart_workflow_input_fields : data.smart_workflow_output_fields
	function open_field(field) { editing = field.id; draft = { ...blank(), ...field }; if (draft.object_spec && typeof draft.object_spec !== 'string') draft.object_spec = JSON.stringify(draft.object_spec, null, 2); if (draft.default_value && typeof draft.default_value === 'object') draft.default_value = JSON.stringify(draft.default_value, null, 2) }
	function new_field() { editing = '__new'; draft = { ...blank(), order: fields().length + 1 } }
	function close_field() { editing = ''; draft = blank() }
	function type_from(value) { if (Array.isArray(value)) { const item = value[0]; return item && typeof item === 'object' ? 'array_object' : typeof item === 'number' ? 'array_number' : typeof item === 'boolean' ? 'array_boolean' : 'array_string' }; if (value === null) return 'string'; if (typeof value === 'number') return Number.isInteger(value) ? 'integer' : 'number'; if (typeof value === 'boolean') return 'boolean'; if (typeof value === 'object') return 'object'; return 'string' }
	function schema_for(value) { if (Array.isArray(value)) return { type: 'array', items: value.length ? schema_for(value[0]) : {} }; if (value && typeof value === 'object') return { type: 'object', properties: Object.fromEntries(Object.entries(value).map(([key, item]) => [key, schema_for(item)])), required: Object.keys(value), additionalProperties: false }; const type = value === null ? 'string' : typeof value; return { type: type === 'number' && Number.isInteger(value) ? 'integer' : type } }
	async function save_field() { if (!draft.name.trim()) { error = 'Field name is required'; return }; let object_spec = draft.object_spec, default_value = draft.default_value; try { if (typeof object_spec === 'string' && object_spec.trim()) object_spec = JSON.parse(object_spec); if (typeof default_value === 'string' && default_value.trim() && (draft.type === 'object' || draft.type.startsWith('array_'))) default_value = JSON.parse(default_value) } catch { error = 'Object schema and JSON defaults must be valid JSON'; return }; saving = true; error = ''; const payload = { name: draft.name.trim(), label: draft.label.trim() || draft.name.trim().replace(/[_-]+/g, ' '), type: draft.type, required: Boolean(draft.required), description: draft.description.trim(), placeholder: draft.placeholder.trim(), default_value, object_spec: draft.type === 'object' ? object_spec : null, order: Number(draft.order) || fields().length + 1, show_in_list: Boolean(draft.show_in_list), searchable: tab === 'input' && Boolean(draft.searchable) }; try { if (editing === '__new') await collection().create(payload); else await collection().update(editing, payload); notice = 'Field configuration saved'; close_field() } catch (err) { error = err instanceof Error ? err.message : String(err) } finally { saving = false } }
	async function remove_field(id) { if (!confirm('Remove this field from the runner configuration?')) return; try { await collection().delete(id) } catch (err) { error = err instanceof Error ? err.message : String(err) } }
	async function import_fields() { let sample; try { sample = JSON.parse(import_json) } catch { error = 'Sample JSON must be valid JSON'; return }; if (!sample || typeof sample !== 'object' || Array.isArray(sample)) { error = 'Paste a JSON object with field names at the top level.'; return }; saving = true; error = ''; try { for (const [name, value] of Object.entries(sample)) { const type = type_from(value); const existing = fields().find((field) => field.name === name); const payload = { name, label: name.replace(/[_-]+/g, ' '), type, required: false, description: '', placeholder: '', default_value: value, object_spec: type === 'object' ? schema_for(value) : null, order: existing?.order || fields().length + 1, show_in_list: Boolean(existing?.show_in_list), searchable: tab === 'input' && Boolean(existing?.searchable) }; if (existing) await collection().update(existing.id, payload); else await collection().create(payload) } notice = 'Fields imported from sample JSON'; import_open = false } catch (err) { error = err instanceof Error ? err.message : String(err) } finally { saving = false } }
	async function save_runner(event) { event.preventDefault(); saving = true; try { const payload = { default_refresh_seconds: Number(config_form.default_refresh_seconds) || 0 }; if (config_form.id) await data.smart_workflow_runner_config.update(config_form.id, payload); else await data.smart_workflow_runner_config.create(payload); notice = 'Runner configuration saved' } catch (err) { error = err instanceof Error ? err.message : String(err) } finally { saving = false } }
</script>

<section class="page"><header><div><p>Workflow form & result schema</p><h2>Configuration</h2><span>Choose what the task form captures, what result fields mean, and which submitted inputs appear in the task list.</span></div><button onclick={() => import_open = true}>Import JSON</button></header>{#if error}<p class="error">{error}</p>{/if}{#if notice}<p class="notice">{notice}</p>{/if}
	<section class="card"><div class="tabs"><button class:active={tab === 'input'} onclick={() => { tab = 'input'; close_field() }}>Input fields <span>{input_fields.length}</span></button><button class:active={tab === 'output'} onclick={() => { tab = 'output'; close_field() }}>Output fields <span>{output_fields.length}</span></button><button class="add" onclick={new_field}>+ Add field</button></div><div class="table-head"><span>Field</span><span>Type</span><span>{tab === 'input' ? 'Task list' : 'Result display'}</span></div><div class="field-rows">{#each fields() as field (field.id)}<article class:open={editing === field.id}><button class="field-row" onclick={() => editing === field.id ? close_field() : open_field(field)}><span><strong>{field.label || field.name}</strong><small>{field.name}{field.required ? ' · required' : ''}</small></span><code>{field.type?.replaceAll('_',' ')}</code><span class="chips">{#if field.show_in_list}<i>list</i>{/if}{#if field.searchable}<i>filter</i>{/if}{#if !field.show_in_list && !field.searchable}<small>Not selected</small>{/if}</span><b>{editing === field.id ? '−' : '+'}</b></button>{#if editing === field.id}<form class="editor" onsubmit={(event) => { event.preventDefault(); void save_field() }}><div class="form-grid"><label>Name<input bind:value={draft.name} required /></label><label>Label<input bind:value={draft.label} placeholder="Friendly label" /></label><label>Type<select bind:value={draft.type}>{#each field_types as type}<option value={type}>{type}</option>{/each}</select></label><label>Order<input type="number" min="1" bind:value={draft.order} /></label><label class="wide">Description<textarea bind:value={draft.description} placeholder="Guidance shown beside the field"></textarea></label><label>Placeholder<input bind:value={draft.placeholder} /></label><label>Default value<input bind:value={draft.default_value} placeholder="Optional" /></label>{#if draft.type === 'object'}<label class="wide">JSON Schema for object<textarea class="schema" bind:value={draft.object_spec} placeholder={'{\n  "type": "object",\n  "properties": { "result": { "type": "number" } },\n  "required": ["result"],\n  "additionalProperties": false\n}'}></textarea></label>{/if}</div><div class="options"><label><input type="checkbox" bind:checked={draft.required} /> Required</label><label><input type="checkbox" bind:checked={draft.show_in_list} /> Show in task list</label>{#if tab === 'input'}<label><input type="checkbox" bind:checked={draft.searchable} /> Dedicated task-list filter</label>{/if}</div><footer><button class="secondary" type="button" onclick={close_field}>Cancel</button>{#if editing !== '__new'}<button class="danger" type="button" onclick={() => remove_field(editing)}>Remove</button>{/if}<button disabled={saving}>{saving ? 'Saving…' : 'Save field'}</button></footer></form>{/if}</article>{:else}<p class="empty">No {tab} fields configured. Add one or import a sample JSON object.</p>{/each}</div></section>
	<section class="card behavior"><h3>Run behavior</h3><p>Costs appear only when SMART returns model usage for a completed workflow. This runner never estimates cost.</p><form onsubmit={save_runner}><label>Default refresh seconds<input type="number" min="0" bind:value={config_form.default_refresh_seconds} /></label><button disabled={saving}>Save</button></form></section>
	{#if import_open}<div class="modal-backdrop" role="presentation"><section class="modal card"><button class="close" onclick={() => import_open = false}>×</button><p>Import fields</p><h3>Paste a sample JSON object</h3><span>Field types are inferred. Object values become object fields with a JSON Schema; existing fields with the same name are updated.</span><textarea bind:value={import_json}></textarea><footer><button class="secondary" onclick={() => import_open = false}>Cancel</button><button onclick={import_fields} disabled={saving}>Import {tab} fields</button></footer></section></div>{/if}
</section>
<style>.page{width:min(1080px,100%);margin:0 auto;display:grid;gap:1rem}header{display:flex;justify-content:space-between;gap:1rem;align-items:flex-end}header p,header h2,header span{margin:0}header p{color:var(--accent-color,#3159db);font-size:.72rem;font-weight:650;letter-spacing:.08em;text-transform:uppercase}header h2{margin:.2rem 0;font-size:1.55rem;font-weight:550;letter-spacing:-.04em}header span,.field-row small,.empty,.behavior p,.modal span{color:var(--muted-ink-color,#637083);font-size:.82rem}.card{border:1px solid var(--border-color,#dbe2ec);border-radius:14px;background:var(--panel-background,#fff)}.tabs{display:flex;gap:.3rem;padding:.7rem;border-bottom:1px solid #e2e8f0}.tabs button{border:0;border-radius:8px;padding:.55rem .7rem;color:#59677c;background:transparent;font:inherit;cursor:pointer}.tabs button.active{color:#3159db;background:#edf2ff}.tabs span{margin-left:.3rem;padding:.12rem .35rem;border-radius:99px;background:#e8edf4;font-size:.7rem}.tabs .add{margin-left:auto;color:#fff;background:var(--accent-color,#3159db)}.table-head,.field-row{display:grid;grid-template-columns:minmax(0,1.7fr) 130px minmax(120px,.8fr) 28px;gap:1rem;align-items:center}.table-head{padding:.65rem 1rem;color:#7a8799;font-size:.68rem;font-weight:650;letter-spacing:.06em;text-transform:uppercase}.field-row{width:100%;padding:.85rem 1rem;border:0;border-top:1px solid #edf1f5;color:var(--ink-color,#172033);background:#fff;text-align:left;font:inherit;cursor:pointer}.field-row:hover{background:#fbfcff}.field-row strong,.field-row small{display:block}.field-row strong{font-size:.88rem;font-weight:600}.field-row small{margin-top:.12rem;font-size:.74rem}.field-row code{width:fit-content;padding:.22rem .45rem;border-radius:6px;color:#52647e;background:#edf2f8;font-size:.7rem}.field-row>b{color:#3159db;font-size:1.1rem;font-weight:400}.chips{display:flex;gap:.3rem}.chips i{padding:.17rem .38rem;border-radius:99px;color:#3159db;background:#edf2ff;font-size:.68rem;font-style:normal}.editor{display:grid;gap:.9rem;padding:1rem 1rem 1.05rem;border-top:1px solid #e4ebf4;background:#fafcff}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.75rem}.wide{grid-column:1/-1}label{display:grid;gap:.32rem;color:#415068;font-size:.78rem;font-weight:600}input,select,textarea{box-sizing:border-box;width:100%;border:1px solid #d5deea;border-radius:8px;padding:.6rem .65rem;color:var(--ink-color,#172033);background:#fff;font:inherit}textarea{min-height:64px;resize:vertical}.schema,.modal textarea{min-height:185px;font:.78rem/1.5 ui-monospace,SFMono-Regular,monospace}.options{display:flex;flex-wrap:wrap;gap:1rem}.options label{display:flex;align-items:center;gap:.4rem;font-size:.8rem}.options input{width:16px}footer{display:flex;justify-content:flex-end;gap:.55rem}button{border:0;border-radius:8px;padding:.6rem .8rem;color:#fff;background:var(--accent-color,#3159db);font:inherit;font-weight:600;cursor:pointer}button:disabled{opacity:.6;cursor:default}.secondary{color:#40516b;background:#edf2f7}.danger{color:#ad3340;background:#fff0f1}.behavior{display:flex;justify-content:space-between;gap:1rem;padding:1rem}.behavior h3,.behavior p{margin:0}.behavior h3{font-size:.92rem}.behavior p{margin-top:.25rem}.behavior form{display:flex;align-items:end;gap:.6rem}.behavior label{min-width:160px}.error,.notice{margin:0;padding:.72rem .8rem;border-radius:9px}.error{color:#b73443;background:#fff1f3}.notice{color:#18724e;background:#e9f8f0}.modal-backdrop{position:fixed;inset:0;z-index:10;display:grid;place-items:center;padding:1rem;background:#17203366}.modal{position:relative;width:min(620px,100%);display:grid;gap:.8rem;padding:1.25rem}.modal p,.modal h3,.modal span{margin:0}.modal p{color:#3159db;font-size:.72rem;text-transform:uppercase;letter-spacing:.07em}.modal h3{font-size:1.05rem}.close{position:absolute;top:.7rem;right:.7rem;padding:.15rem .45rem;color:#667085;background:#eef2f6;font-size:1.15rem}@media(max-width:650px){header,.behavior{align-items:stretch;flex-direction:column}.table-head{display:none}.field-row{grid-template-columns:1fr auto 24px}.field-row code{display:none}.field-row .chips{justify-self:end}.form-grid{grid-template-columns:1fr}.wide{grid-column:auto}.behavior form{align-items:stretch;flex-direction:column}}</style>
